@Composable
private fun EpisodesStatusMessage(
    icon: String,
    message: String
) {
    Row(
        verticalAlignment =
            Alignment.CenterVertically,
        modifier = Modifier
            .padding(
                start = 24.dp,
                end = 24.dp,
                bottom = 12.dp
