        if (icon == "⏳") {
            CircularProgressIndicator(
                modifier = Modifier.size(18.dp),
                color = KBAccent,
                strokeWidth = 2.dp
            )
        } else {
            Text(
                icon,
                style =
                    MaterialTheme.typography.bodyMedium
            )
        }

        Text(
            message,
            color = KBTextLo,
            style =
                MaterialTheme.typography.bodyMedium,
            modifier = Modifier.padding(
                start = 8.dp
            )
        )
    }
}

new:
@Composable
private fun EpisodesStatusMessage(
    icon: String,
    message: String
) {
    // The app's one status card, inline in the episodes list. The old
    // hand-rolled chip row was the last browse-style status outside
    // KBStatusMessage; its "⏳" glyph is now the shared loading flag.
    KBStatusMessage(
        loading = icon == "⏳",
        icon = icon,
        message = message,
        modifier = Modifier
            .fillMaxWidth()
            .padding(start = 24.dp, end = 24.dp, bottom = 12.dp)
    )
}
